/// <summary>
/// Finds the icon row's vertical extent inside a zone from its vertical border lines: every
/// column in the icon strip zone whose contiguous ink run is roughly one icon tall
/// (<see cref="BorderRunMinRatio"/>..<see cref="BorderRunMaxRatio"/> of
/// <paramref name="expectedIconHeight"/>) is a border-line candidate. Horizontal separator
/// lines and their shading are only a few px tall, glyph strokes are shorter than a cell, and a
/// thick border that merges with a separator above or below overshoots the max — none of them
/// qualify. The median top/bottom of the candidates (after discarding those that do not mostly
/// overlap the median) is the row's icon extent; the bottom is then pinned on the dark bevel
/// line (see <see cref="DarkLineMaxValue"/>) so shadow under the icons cannot stretch it.
/// Returns null when too few candidates exist.
/// </summary>
/// <summary>
/// Finds the icon row by trying every placement in the zone and keeping the one that
/// segments into the most consistent cells, rather than by voting on ink-run lengths.
///
/// The vote was swamped in rows with few icons (RUNE-12). On the user's capture, a two-icon
/// row offered 8 genuine border-line runs and ~18 spurious ones of the same length — the
/// gilded cell's own glyph strokes running unbroken into its bevel, the shadow beneath and
/// the row separator — so the median landed 26px low and the whole row was misplaced. A row
/// with 5-6 icons has enough genuine border columns to outvote the same noise, which is why
/// this only ever showed on short rows.
///
/// Searching is affordable because the panel is read once per session and then latched
/// (<c>LeaguePricingWorker.LatchRuneRows</c>), not re-read every cycle. It also scores on the
/// thing actually being looked for — a row of equal, square, evenly pitched cells — instead
/// of on a proxy that glyph ink can imitate.
/// </summary>
internal static (int Top, int Bottom)? LocateIconRow(
    byte[] rgb, int width, int height, int stride, int zoneTop, int zoneBottomExclusive, int expectedIconHeight, int textCentreY = -1)
{
    if (zoneBottomExclusive - zoneTop < MinCellPx || expectedIconHeight <= 0) return null;

    var best = (Score: int.MinValue, Top: 0, Bottom: 0);
    foreach (var rowHeight in CandidateRowHeights(expectedIconHeight))
    {
        for (var top = zoneTop; top + rowHeight <= zoneBottomExclusive; top++)
        {
            var bottom = top + rowHeight - 1;
            var score = ScorePlacement(rgb, width, height, stride, top, bottom);
            if (score == int.MinValue) continue;

            // The zone is wide enough to reach the next row's icons, and a neighbour's cells
            // segment just as convincingly as this row's — so without this a row could adopt
            // the row below's icons and two rows would mark the same cells twice. Pulling
            // towards this row's own text line costs less than one cell, so it only ever
            // decides between placements that are otherwise equally good.
            if (textCentreY >= 0)
                score -= Math.Abs(((top + bottom) / 2) - textCentreY) * RowDistancePenalty;

            if (score > best.Score)
                best = (score, top, bottom);
        }
    }

    if (best.Score <= 0)
        return LocateIconRowByInkRuns(rgb, width, stride, zoneTop, zoneBottomExclusive, expectedIconHeight);

    return SnapToSquareCells(rgb, width, height, stride, best.Top, best.Bottom);
}

/// <summary>
/// Re-derives the band's height from its own plain cells' width, keeping the bottom where the
/// search put it (on the bevel line, see <see cref="BevelLineWeight"/>). Only when at least two
/// plain cells agree and the change is within <see cref="SquareSnapTolerance"/>: a row with a
/// single measured cell has nothing to vote with, and a larger disagreement means the cells,
/// not the band, are the thing mis-measured.
/// </summary>
private static (int Top, int Bottom) SnapToSquareCells(byte[] rgb, int width, int height, int stride, int top, int bottom)
{
    var cells = SegmentIconCells(rgb, width, height, stride, top, bottom);
    var plainWidths = cells.Where(c => !c.IsGilded).Select(c => c.Bounds.Width).ToList();
    if (plainWidths.Count < 2) return (top, bottom);

    var cellWidth = Median(plainWidths);
    var rowHeight = bottom - top + 1;
    if (cellWidth < MinCellPx || Math.Abs(cellWidth - rowHeight) > SquareSnapTolerance) return (top, bottom);

    var snappedTop = Math.Max(0, bottom - cellWidth + 1);
    return (snappedTop, bottom);
}

